manifest=json.loads((root/'source/creative.json').read_text())
assets=root/'assets'; assets.mkdir(exist_ok=True)
fonts={'archivo':'https://fonts.gstatic.com/s/archivo/v25/k3k6o8UDI-1M0wlSV9XAw6lQkqWY8Q82sJaRE-NWIDdgffTTNDNp8A.ttf','archivo-black':'https://fonts.gstatic.com/s/archivoblack/v23/HTxqL289NzCGg4MzN6KJ7eW6OYs.ttf'}
for name,url in fonts.items():
 p=assets/(name+'.ttf')
 if not p.exists(): p.write_bytes(urllib.request.urlopen(url,timeout=20).read())
for name in ['archivo','archivoblack']:
 p=assets/(name+'-OFL.txt')
 if not p.exists(): p.write_bytes(urllib.request.urlopen('https://raw.githubusercontent.com/google/fonts/main/ofl/'+name+'/OFL.txt',timeout=20).read())
