hero='data:image/webp;base64,'+base64.b64encode((assets/'hero.webp').read_bytes()).decode()
def doc(name):
 s=(root/name).read_text(); out=[]
 for line in s.splitlines():
  safe=html.escape(line)
  safe=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',safe)
  if line.startswith('# '): out.append('<h3>'+safe[2:]+'</h3>')
  elif line.startswith('## '): out.append('<h4>'+safe[3:]+'</h4>')
  elif line.strip(): out.append('<p>'+safe+'</p>')
 return ''.join(out)
